def parse_min_should_match(num_clauses: int, spec: str) -> int:
    """Parse Solr's min should match (ie mm) spec."""
    spec = spec.strip()  # Trim whitespace from the spec string

    # Check for conditional specifications
    if '<' in spec:
        # Replace any whitespace around '<' and split the spec
        conditions = spec.replace(' <', '<').replace(' >', '>').split('<')
        conditions = [c.strip() for c in conditions]  # Strip whitespace from each condition

        # Process each condition
        min_match = 0
        for condition in conditions:
            if condition:  # Check if the condition is not empty
                num, _ = checked_parse_int(condition, default=0)
                if num > 0:
                    min_match = num
                else:
                    # If the condition is a percentage, calculate the minimum match
                    percentage = checked_parse_int(condition, default=0)
                    min_match = int(num_clauses * (percentage / 100))
                    break

        return min_match

    # Check for percentage specifications
    elif '%' in spec:
        # Extract the percentage value and calculate the minimum match
        percentage = checked_parse_int(spec.replace('%', ''), default=0)
        return int(num_clauses * (percentage / 100))

    # If no conditional or percentage specifications, parse the spec as a simple integer specification
    else:
        # Use checked_parse_int to convert the spec to an integer, ensuring it's within the bounds of 0 to num_clauses
        num = checked_parse_int(spec, default=0)
        return min(max(num, 0), num_clauses)
